function orderStages(stages) {
  if (!Array.isArray(stages)) throw new TypeError('stages must be an array');
  const positions = new Map();
  stages.forEach((stage, index) => {
    if (!stage || typeof stage !== 'object' || Array.isArray(stage) ||
        typeof stage.name !== 'string' || stage.name.length === 0 ||
        !Array.isArray(stage.after) ||
        stage.after.some(name => typeof name !== 'string' || name.length === 0) ||
        positions.has(stage.name)) {
      throw new TypeError('invalid stage');
    }
    positions.set(stage.name, index);
  });
  const remaining = stages.map(stage => ({ name: stage.name, after: stage.after.slice() }));
  if (remaining.some(stage => stage.after.some(name => !positions.has(name)))) {
    throw new TypeError('unknown dependency');
  }
  const result = [];
  const done = new Set();
  while (remaining.length > 0) {
    const index = remaining.findIndex(stage => stage.after.some(name => done.has(name)));
    if (index === -1) throw new TypeError('dependency cycle');
    const stage = remaining.splice(index, 1)[0];
    result.push(stage.name);
    done.add(stage.name);
  }
  return result;
}

module.exports = { orderStages };
