'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['orderStages']);
const { orderStages } = api;

const stages = [
  { name: 'publish', after: ['build', 'test'] },
  { name: 'lint', after: [] },
  { name: 'build', after: ['lint'] },
  { name: 'docs', after: [] },
  { name: 'test', after: ['build'] }
];
const snapshot = structuredClone(stages);
assert.deepEqual(orderStages(stages), ['lint', 'build', 'docs', 'test', 'publish']);
assert.deepEqual(stages, snapshot);
assert.deepEqual(orderStages([]), []);
assert.deepEqual(orderStages([{ name: 'b', after: [] }, { name: 'a', after: [] }]), ['b', 'a']);
assert.deepEqual(orderStages([{ name: 'a', after: [] }, { name: 'b', after: ['a', 'a'] }]), ['a', 'b']);

for (const bad of [null, {}, 'stages']) assert.throws(() => orderStages(bad), TypeError);
for (const badStage of [null, [], {}, { name: '', after: [] }, { name: 1, after: [] }, { name: 'a', after: null }, { name: 'a', after: [''] }, { name: 'a', after: [1] }]) {
  assert.throws(() => orderStages([badStage]), TypeError);
}
assert.throws(() => orderStages([{ name: 'a', after: [] }, { name: 'a', after: [] }]), TypeError);
assert.throws(() => orderStages([{ name: 'a', after: ['missing'] }]), TypeError);
assert.throws(() => orderStages([{ name: 'a', after: ['a'] }]), TypeError);
assert.throws(() => orderStages([{ name: 'a', after: ['b'] }, { name: 'b', after: ['a'] }]), TypeError);

